import React, { useMemo, useState } from "react";
import styled from "styled-components";

interface PublicationLink {
  label: string;
  href: string;
}

interface Publication {
  title: string;
  thumb: string;
  description: string;
  authors: string;
  venue: string;
  links: PublicationLink[];
  year?: string;
}

const publications: Publication[] = [
  {
    title: "Uncovering the Internet’s Hidden Values: An Empirical Study of Desirable Behavior Using Highly-Upvoted Content on Reddit.",
    thumb: "ICWSM 2026",
    description: "Analyzes highly-upvoted Reddit content to surface community-valued behaviors and norms.",
    authors: "A. Goyal, C. Lambert, Y. Jain, E. Chandrasekharan",
    venue: "International AAAI Conference on Web and Social Media (ICWSM 2026)",
    year: "2026",
    links: [],
  },
  {
    title: "PLAID: Supporting Computing Instructors to Identify Domain-Specific Programming Plans at Scale.",
    thumb: "CHI 2025",
    description: "Human-AI workflow that helps instructors surface domain-specific programming plans in student code at scale.",
    authors: "Y. Jain*, M. Demirtas*, K. Cunningham",
    venue: "ACM CHI Conference on Human Factors in Computing Systems (CHI 2025)",
    year: "2025",
    links: [],
  },
  {
    title: "Exploring the Potential of Large Language Models for Estimating the Reading Comprehension Question Difficulty.",
    thumb: "HCII 2025",
    description: "Benchmarks LLM estimates of question difficulty against human annotations for reading comprehension tasks.",
    authors: "Y. Jain, J. Hollander, A. He, S. Tang, L. Zhang, J. Sabatini",
    venue: "International Conference on Human-Computer Interaction (HCII 2025)",
    year: "2025",
    links: [],
  },
  {
    title: "Linguistic Comparison of AI- and Human-Written Responses to Online Mental Health Queries.",
    thumb: "Under Review",
    description: "Compares language patterns in AI- versus human-written mental health responses in online communities.",
    authors: "K. Saha, Y. Jain, M. De Choudhury",
    venue: "Nature: Artificial Intelligence (under review, submitted Apr 2025)",
    year: "2025",
    links: [],
  },
  {
    title: "Online Communities as a Support System for Alzheimer’s and Dementia Care: Large-scale Exploratory Study.",
    thumb: "JMIR Aging 2025",
    description: "Large-scale analysis of Alzheimer’s and dementia support forums as informal care resources.",
    authors: "S. Kaliappan, C. Liu, Y. Jain, R. Karkar, K. Saha",
    venue: "JMIR Aging 2025",
    year: "2025",
    links: [],
  },
  {
    title: "AI vs Humans for Online Support: Comparing the Language of Responses from LLMs and Online Communities of Alzheimer’s Disease.",
    thumb: "TOCHI 2025",
    description: "Contrasts linguistic features of LLM-generated and human responses in Alzheimer’s support contexts.",
    authors: "K. Saha, Y. Jain, C. Liu, S. Kaliappan, R. Karkar",
    venue: "ACM Transactions on Computing for Healthcare 2025",
    year: "2025",
    links: [],
  },
  {
    title: "Examining the Efficacy of Hashtag-Based Bans on Instagram.",
